"""Official CKAN discovery; no fixed CSV download links."""
import hashlib, json, re, time, urllib.request
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path
from urllib.parse import urlencode, urlparse
from .config import CONFIG

def api(action, **params):
    url=CONFIG['ckan_url']+'/'+action+'?'+urlencode(params)
    for attempt in range(3):
        try:
            with urllib.request.urlopen(url, timeout=CONFIG['timeout_seconds']) as response:
                payload=json.load(response)
            if not payload.get('success'): raise ValueError('CKAN returned success=false')
            return payload['result']
        except Exception:
            if attempt==2: raise
            time.sleep(1+attempt)

def discover():
    resources=[]; packages={}
    for kind,slug in CONFIG['datasets'].items():
        p=api('package_show',id=slug); packages[slug]=p
        selected=[]
        for r in p['resources']:
            fmt=r.get('format','').upper()
            if fmt not in ('CSV','JSON'): continue
            url=r['url']; basename=urlparse(url).path.rsplit('/',1)[-1].lower()
            role='metadata' if fmt=='JSON' else ('transactions' if 'darijumi' in basename else 'coordinates')
            selected.append(dict(r,kind=kind,role=role,package=slug))
        if not any(r['role']=='transactions' for r in selected) or not any(r['role']=='coordinates' for r in selected):
            raise ValueError(f'Missing transaction/coordinate resource: {slug}')
        resources.extend(selected)
    p=api('package_show',id='nekustama-ipasuma-tirgus-datu-bazes-atvertie-dati');packages[p['name']]=p
    legacy=[dict(r,kind='legacy',role='archive',package=p['name']) for r in p['resources'] if 'nitis_csv_' in r['url'].lower() and r.get('format','').upper()=='ZIP']
    years={int(y) for r in legacy for y in re.findall(r'nitis_csv_(20\d{2})',r['url'])}
    if not set(range(2012,2016)).issubset(years):raise ValueError('Required 2012–2015 archives unavailable; previous database retained')
    if set(range(2012,max(years)+1))!=years:raise ValueError('Gap in official annual archives')
    resources.extend(legacy)
    p=api('package_show',id='varis-atvertie-dati');packages[p['name']]=p
    for r in p['resources']:
        name=urlparse(r['url']).path.rsplit('/',1)[-1]
        if name in [f'aw_{x}{suffix}' for x in ('novads','pagasts','pilseta','ciems') for suffix in ('.csv','_metadata.json')]:
            resources.append(dict(r,kind='territory',role=name,package=p['name']))
        if name in ('aw_novads_his.csv','aw_pagasts_his.csv','aw_pilseta_his.csv'):
            resources.append(dict(r,kind='territory_history',role=name,package=p['name']))
    if sum(r['kind']=='territory' and r['format']=='CSV' for r in resources)!=4:raise ValueError('Missing VAR territorial references')
    p=api('package_show',id='atr');packages[p['name']]=p
    geo=[r for r in p['resources'] if r.get('format','').lower()=='geojson']
    if geo:
        r=max(geo,key=lambda r:max(re.findall(r'20\d{2}',r['name']) or ['0']))
        resources.append(dict(r,kind='geometry',role='boundaries',package=p['name']))
    return resources, packages

def sha256(path):
    with Path(path).open('rb') as f:return hashlib.file_digest(f,'sha256').hexdigest()

def download(resource, directory, now):
    url=resource['url']
    if urlparse(url).scheme!='https': raise ValueError('Only HTTPS resources accepted')
    if not re.fullmatch(r'[A-Za-z0-9_-]+',resource['id']):raise ValueError('Invalid resource identifier')
    path=directory/(resource['id']+'.'+resource['format'].lower())
    budget=int(CONFIG['max_download_gb']*1024**3)
    probe=urllib.request.urlopen(urllib.request.Request(url,headers={'Range':'bytes=0-0'}),timeout=CONFIG['timeout_seconds'])
    content_range=probe.headers.get('Content-Range','')
    if probe.status==206 and '/' in content_range:
        total=int(content_range.split('/')[-1]);etag=probe.headers.get('ETag');probe.close()
        if total>budget:raise ValueError('Download disk budget exceeded')
        if total>16*1024**2:
            step=16*1024**2;segments=[(i,start,min(start+step,total)-1) for i,start in enumerate(range(0,total,step))]
            def part(segment):
                i,start,end=segment;target=path.with_suffix(path.suffix+f'.part{i}')
                headers={'Range':f'bytes={start}-{end}'}
                if etag:headers['If-Match']=etag
                with urllib.request.urlopen(urllib.request.Request(url,headers=headers),timeout=CONFIG['timeout_seconds']) as response,target.open('wb') as out:
                    if response.status!=206 or response.headers.get('Content-Range')!=f'bytes {start}-{end}/{total}':raise ValueError('Unexpected ranged response')
                    if etag and response.headers.get('ETag')!=etag:raise ValueError('Resource changed during download')
                    while block:=response.read(1024**2):out.write(block)
                if target.stat().st_size!=end-start+1:raise ValueError('Truncated range')
                return target
            with ThreadPoolExecutor(max_workers=4) as pool:parts=list(pool.map(part,segments))
            with path.open('wb') as out:
                for target in parts:
                    with target.open('rb') as inp:
                        while block:=inp.read(1024**2):out.write(block)
                    target.unlink()
            size=path.stat().st_size
            if size!=total:raise ValueError('Truncated combined file')
            return {**resource,'file':path.name,'size':size,'sha256':sha256(path),'downloaded_at':now,'status':'downloaded','period':';'.join(re.findall(r'\d{8}-\d{8}',url))}
        response=urllib.request.urlopen(url,timeout=CONFIG['timeout_seconds'])
    else:response=probe
    with response, path.open('wb') as out:
        size=0
        while block:=response.read(1024*1024):
            size+=len(block)
            if size>budget:raise ValueError('Download disk budget exceeded')
            out.write(block)
        expected=response.headers.get('Content-Length')
        if expected and int(expected)!=size:raise ValueError('Truncated download')
    if size==0:raise ValueError('Empty resource')
    return {**resource,'file':path.name,'size':size,'sha256':sha256(path),'downloaded_at':now,'status':'downloaded','period':';'.join(re.findall(r'\d{8}-\d{8}',url))}

