"""Conservative current-territory lookup for old source names.

Only fills missing links. Original source fields, money and dates are untouched.
The active VAR hierarchy supplies all codes and current municipality names.
"""
from collections import defaultdict
import json
import pandas as pd

# Former single-unit municipalities whose territory is represented by this parish.
# Rojas novads also contained Mersrags before 2011; only its common parent is safe then.
SINGLE_PARISH = {
    'Alsungas nov.': 'Alsungas pag.', 'Baltinavas nov.': 'Baltinavas pag.',
    'Carnikavas nov.': 'Carnikavas pag.', 'Garkalnes nov.': 'Garkalnes pag.',
    'Mālpils nov.': 'Mālpils pag.', 'Mērsraga nov.': 'Mērsraga pag.',
    'Rojas nov.': 'Rojas pag.', 'Sējas nov.': 'Sējas pag.',
    'Skrīveru nov.': 'Skrīveru pag.', 'Stopiņu nov.': 'Stopiņu pag.',
}
FIELDS = ('district_code','district','municipality_atr','city_code','city',
          'parish_code','parish','village_code','village','territory_method','flags')


class Resolver:
    def __init__(self, refs):
        self.refs = refs
        self.active = {r['KODS']: r for r in refs if r['STATUSS'] == 'EKS'}
        self.names = defaultdict(list)
        self.old_names = defaultdict(list)
        for r in refs:
            (self.names if r['STATUSS']=='EKS' else self.old_names)[r['TIPS_CD'],r['NOSAUKUMS']].append(r)

    def unique(self, typ, name):
        found = self.names[typ, name]
        return found[0] if name and len(found)==1 else None

    def municipality(self, local):
        if local['TIPS_CD']=='104' and local['VKUR_TIPS']=='101':
            return local
        parent = self.active.get(local['VKUR_CD'])
        return parent if parent and parent['TIPS_CD']=='113' else None

    def resolve(self, source, existing_code='', transaction_date=None):
        district=(source.get('ArDistrict') or '').strip()
        city=(source.get('ArCity') or '').strip()
        parish=(source.get('ArParish') or '').strip()
        if city and parish:
            return None, 'conflicting_city_and_parish'
        local=self.unique('104',city) if city else self.unique('105',parish)
        method='current_local_parent'
        if not local and (city or parish):
            return None, 'local_name_not_unique'
        if not local and district in SINGLE_PARISH:
            local=self.unique('105',SINGLE_PARISH[district])
            method='former_single_parish_municipality'
        # Iecava gained city status: the former parish alone cannot distinguish
        # present-day city and parish. Recover their common municipality only.
        district_only = False
        day = str(transaction_date or '')[:10]
        if (parish=='Iecavas pag.' or district=='Iecavas nov.') and (not day or day<'2021-07-01'):
            local=self.unique('105','Iecavas pag.')
            district_only=True
            method='former_iecava_municipality_only'
        if district=='Rojas nov.' and not city and not parish and (not day or day<'2011-01-03'):
            district_only=True
            method='former_roja_municipality_only'
        if not local:
            return None,'insufficient_local_evidence'
        parent=self.municipality(local)
        if not parent:
            return None,'missing_current_parent'
        if existing_code and existing_code!=parent['KODS']:
            return None,'source_spatial_conflict'
        current_district=self.unique('113',district)
        if current_district and current_district['KODS']!=parent['KODS']:
            return None,'conflicting_current_district'
        if district and not current_district and not self.old_names['113',district]:
            return None,'unknown_historical_district'
        # Require historical membership for a retired municipality. A global
        # name match alone must not silently override a contradictory parent.
        if district and not current_district and district not in SINGLE_PARISH and district!='Iecavas nov.':
            old_codes={r['KODS'] for r in self.old_names['113',district]}
            related=any(r['TIPS_CD']==local['TIPS_CD'] and r['NOSAUKUMS']==local['NOSAUKUMS'] and r['VKUR_CD'] in old_codes for r in self.refs)
            # Some current VAR rows retain their code after transfer; historical
            # rows are loaded separately by the evidence audit when available.
            related=related or any(r.get('KODS')==local['KODS'] and district in r.get('STD','').split(', ') for r in self.refs)
            if not related:
                return None,'historical_membership_not_verified'
        result={'district_code':parent['KODS'],'district':parent['NOSAUKUMS'],
                'municipality_atr':parent['ATRIB'],'city_code':'','city':'',
                'parish_code':'','parish':'','village_code':'','village':''}
        if not district_only:
            kind='city' if local['TIPS_CD']=='104' else 'parish'
            result[kind+'_code']=local['KODS'];result[kind]=local['NOSAUKUMS']
        return result,method


def apply_patches(con, patches):
    con.execute('CREATE TABLE IF NOT EXISTS territory_reform_audit(transaction_id VARCHAR, before_json VARCHAR, after_json VARCHAR, evidence_json VARCHAR)')
    if not patches:
        return 0
    updates=[]
    for patch in patches:
        after=patch['after']
        updates.append({'transaction_id':patch['transaction_id'],**after})
    con.register('reform_updates',pd.DataFrame(updates))
    con.execute('UPDATE transactions SET '+','.join(f'{f}=r.{f}' for f in FIELDS)+' FROM reform_updates r WHERE transactions.transaction_id=r.transaction_id')
    con.execute("DELETE FROM quality_flags WHERE rule='territory_unmatched' AND transaction_id IN (SELECT transaction_id FROM reform_updates WHERE district_code<>'')")
    con.executemany('INSERT INTO territory_reform_audit VALUES (?,?,?,?)',[(p['transaction_id'],json.dumps(p['before'],ensure_ascii=False),json.dumps(p['after'],ensure_ascii=False),json.dumps(p['evidence'],ensure_ascii=False)) for p in patches])
    con.unregister('reform_updates')
    return len(patches)


def plan_recovery(con, extra_refs=()):
    refs=con.execute('SELECT * FROM territories').df().to_dict('records')
    if con.execute("SELECT count(*) FROM information_schema.tables WHERE table_name='territory_history'").fetchone()[0]:
        history=con.execute('SELECT * FROM territory_history').df().to_dict('records')
        refs.extend({**r,'STATUSS':'HIS'} for r in history)
    resolver=Resolver(refs+list(extra_refs))
    targets=con.execute("""SELECT * FROM transactions WHERE valid AND district_code=''
        AND city_code='' AND parish_code='' AND territory_method='unmatched'
        AND NOT contains(flags,'cross_dataset') AND NOT contains(flags,'multiple_source_territories')""").df().to_dict('records')
    patches=[];pending=[]
    for row in targets:
        source={'ArDistrict':row['source_district'],'ArCity':row['source_city'],'ArParish':row['source_parish']}
        resolved,method=resolver.resolve(source,transaction_date=row['date'])
        if not resolved:
            pending.append({'transaction_id':row['transaction_id'],'reason':method,**source})
            continue
        before={key:row[key] for key in FIELDS}
        after={**resolved,'territory_method':method,'flags':' | '.join(f for f in row['flags'].split(' | ') if f!='territory_unmatched')}
        patches.append({'transaction_id':row['transaction_id'],'before':before,'after':after,
                        'evidence':{'method':method,'source':source,'reference':'Valsts adrešu reģistrs','source_values_preserved':True}})
    return patches,pending


def recover_reform(con):
    patches,_=plan_recovery(con)
    count=apply_patches(con,patches)
    patches,_=plan_local_recovery(con)
    return count+apply_patches(con,patches)


def plan_local_recovery(con):
    """Resolve a missing local unit even when coordinates already found its parent."""
    from .territory_recovery import signature
    refs=con.execute('SELECT * FROM territories').df().to_dict('records')
    if con.execute("SELECT count(*) FROM information_schema.tables WHERE table_name='territory_history'").fetchone()[0]:
        refs.extend({**r,'STATUSS':'HIS'} for r in con.execute('SELECT * FROM territory_history').df().to_dict('records'))
    resolver=Resolver(refs)
    targets=con.execute("""SELECT * FROM transactions WHERE valid AND district_code<>''
        AND city_code='' AND parish_code='' AND territory_method<>'multiple_current_territories'
        AND NOT contains(flags,'cross_dataset') AND NOT contains(flags,'multiple_source_territories')""").df().to_dict('records')
    raw=defaultdict(lambda:defaultdict(list));resources=defaultdict(set);kinds=defaultdict(set)
    for tid,origin,kind,rid,payload in con.execute('SELECT transaction_id,origin,kind,resource_id,payload FROM raw_records WHERE transaction_id IN (SELECT unnest(?))',[[r['transaction_id'] for r in targets]]).fetchall():
        raw[tid][origin].append(json.loads(payload));kinds[tid].add(kind)
        if origin=='legacy':resources[tid].add(rid)
    patches=[];pending=[]
    for row in targets:
        tid=row['transaction_id']
        source={f:row[k] for f,k in [('ArDistrict','source_district'),('ArCity','source_city'),('ArParish','source_parish')]}
        resolved,reason=resolver.resolve(source,row['district_code'],row['date'])
        method='current_source_local';evidence={'source':source}
        if not resolved and reason in ('source_spatial_conflict','conflicting_current_district','conflicting_city_and_parish'):
            pending.append({'transaction_id':tid,'reason':reason});continue
        if not resolved or not (resolved['city_code'] or resolved['parish_code']):
            modern,legacy=raw[tid]['modern'],raw[tid]['legacy']
            if len(kinds[tid])!=1 or not modern or not legacy or signature(modern) is None or signature(modern)!=signature(legacy):
                pending.append({'transaction_id':tid,'reason':reason});continue
            # Do not replace explicit modern local names with a different archive interpretation.
            if any(r.get('ArCity') or r.get('ArParish') for r in modern):
                pending.append({'transaction_id':tid,'reason':'explicit_modern_local_unresolved'});continue
            names={tuple((r.get(k) or '').strip() for k in ('ArDistrict','ArCity','ArParish')) for r in legacy}
            if len(names)!=1:
                pending.append({'transaction_id':tid,'reason':'conflicting_archive_territories'});continue
            source=dict(zip(('ArDistrict','ArCity','ArParish'),next(iter(names))))
            resolved,reason=resolver.resolve(source,row['district_code'],row['date'])
            method='verified_archive_reform_local'
            evidence={'source':source,'archive_resources':sorted(resources[tid]),'identity_check':'date_amount_cadastral_ids'}
        if not resolved or not (resolved['city_code'] or resolved['parish_code']):
            pending.append({'transaction_id':tid,'reason':reason});continue
        before={k:row[k] for k in FIELDS}
        after={**before,**{k:resolved[k] for k in ('city_code','city','parish_code','parish')},'territory_method':row['territory_method']+'+'+method}
        patches.append({'transaction_id':tid,'before':before,'after':after,'evidence':{**evidence,'method':method,'reference':'Valsts adrešu reģistrs','source_values_preserved':True}})
    return patches,pending
